//! Simulation — pointing the harness at data whose truth is already known.
//!
//! Every other module here measures a strategy. This one measures the MEASURING INSTRUMENT, which is
//! the thing you cannot check with real data: on a real series nobody knows what the right answer
//! was, so a harness that is subtly broken looks exactly like a harness that found something.
//!
//! Two questions, and the second is the one that matters:
//!
//! 1. **Does it reach the right verdict on a process whose truth we set?** Random walks contain
//!    nothing, and anything reported as a finding on one is the harness lying.
//! 2. **What does testing many signals actually do to a result?** [`multiple_testing`] generates a
//!    pile of signals that are KNOWN to be worthless, runs them on data that is KNOWN to be noise,
//!    and reports how many clear the conventional bar. The answer is not zero, and that number is
//!    the single most useful thing in this file.
use crate::evaluate::{evaluate, evaluate_all, t_required_for, EvalOptions, Evaluation, Signal, Verdict};
use crate::money::{money, Currency};
use crate::series::{is_weekend, unverified_series, Bar, BarDate, SeriesMeta, VerifiedSeries};
use crate::signals::{default_battery, NullControl};

/// A deterministic generator, so a simulation is reproducible and two runs can be compared.
struct Rng(u64);

impl Rng {
    fn next_unit(&mut self) -> f64 {
        self.0 = self.0.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
        ((self.0 >> 33) as f64 / (1u64 << 31) as f64) * 2.0 - 1.0
    }
}

/// `n` consecutive trading days from a Monday.
pub fn trading_days(n: usize, from: &str) -> Vec<String> {
    let mut out = Vec::with_capacity(n);
    let mut d = from.to_string();
    while out.len() < n {
        if !is_weekend(&d) {
            out.push(d.clone());
        }
        let next = crate::obligations::add_days(&d, 1);
        if next == d {
            break;
        }
        d = next;
    }
    out
}

/// What kind of world the prices came from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Shape {
    /// No drift. Contains NOTHING, by construction.
    Noise,
    /// A steady upward drift with noise on top.
    Trend,
    /// A trend that gives most of it back in one stretch.
    Crash,
    /// Yesterday's direction predicts today's — structure that real markets do not have.
    Autocorrelated,
}

impl Shape {
    pub fn label(self) -> &'static str {
        match self {
            Shape::Noise => "noise",
            Shape::Trend => "trend",
            Shape::Crash => "crash",
            Shape::Autocorrelated => "autocorrelated",
        }
    }

    /// What a correct harness should conclude, and WHY that is knowable here.
    pub fn expectation(self) -> &'static str {
        match self {
            Shape::Noise => "nothing found — a driftless walk contains no signal, so anything reported as one is the instrument lying",
            Shape::Trend => "nothing beats holding — timing signals give up upside in a trend, and a battery that claims otherwise is fitting",
            Shape::Crash => "nothing found, but the trend filter should hold a SMALLER drawdown than buying and holding",
            Shape::Autocorrelated => "the battery contains a signal fast enough to see this — real structure that no signal in the battery can read is a gap in the BATTERY, not in the harness, which is proved able to find it elsewhere",
        }
    }
}

/// Build a synthetic series of a known shape.
pub fn synth(shape: Shape, n: usize, seed: u64) -> Vec<Bar> {
    let dates = trading_days(n, "2020-01-06");
    let mut rng = Rng(seed);
    let mut px = 100.0_f64;
    let mut up = true;
    let mut out = Vec::with_capacity(n);
    for (i, date) in dates.iter().enumerate() {
        let u = rng.next_unit();
        let open = px;
        let step = match shape {
            Shape::Noise => u * 0.012,
            Shape::Trend => 0.0006 + u * 0.012,
            // Two thirds up, then a sustained fall that takes most of it back.
            Shape::Crash => {
                if i < n * 2 / 3 {
                    0.0008 + u * 0.010
                } else {
                    -0.0016 + u * 0.016
                }
            }
            Shape::Autocorrelated => {
                if u > 0.75 {
                    up = !up;
                }
                if up { 0.004 } else { -0.004 }
            }
        };
        px *= 1.0 + step;
        if px < 1.0 {
            px = 1.0; // a price floor, so a bad draw cannot make the series non-positive
        }
        let (o, c) = (open, px);
        out.push(Bar {
            date_i: BarDate::new(date),
            open: money((o * 10_000.0).round() as i64, Currency::USD),
            high: money((o.max(c) * 1.002 * 10_000.0).round() as i64, Currency::USD),
            low: money((o.min(c) * 0.998 * 10_000.0).round() as i64, Currency::USD),
            close: money((c * 10_000.0).round() as i64, Currency::USD),
            volume: Some(1_000_000),
        });
    }
    out
}

pub fn series_of(shape: Shape, n: usize, seed: u64) -> VerifiedSeries {
    let bars = synth(shape, n, seed);
    let meta = SeriesMeta {
        symbol: shape.label().to_uppercase(),
        adjusted: Some(true),
        // UNDECLARED even here: a single simulated instrument says nothing about what would be
        // missing from a universe, and pretending otherwise in a simulation would teach the wrong
        // habit to whatever reads it next.
        survivorship_free: None,
        source: "simulated".to_string(),
        minor_per_unit: 10_000,
    };
    unverified_series(&bars, meta, "SIMULATED DATA — generated here, not a market").expect("a caveat is given")
}

#[derive(Debug, Clone, PartialEq)]
pub struct RegimeResult {
    pub shape: Shape,
    pub expectation: &'static str,
    pub results: Vec<Evaluation>,
    /// Did the harness reach the verdict this shape demands?
    pub matched: bool,
    /// What was observed, in the terms the expectation is phrased in.
    pub observed: String,
}

/// Run the battery over every known shape and check the verdicts against what the shape guarantees.
///
/// A mismatch is NOT automatically the harness being wrong — an expectation can be too strong, and
/// saying which is a judgement. What it is, always, is something to go and look at, which is more
/// than a green test suite over real data can ever offer.
pub fn run_regimes(bars: usize, opts: &EvalOptions) -> Vec<RegimeResult> {
    let mut out = Vec::new();
    for shape in [Shape::Noise, Shape::Trend, Shape::Crash, Shape::Autocorrelated] {
        let s = series_of(shape, bars, 20_260_101 + shape as u64);
        let battery = default_battery();
        let refs: Vec<&dyn Signal> = battery.iter().map(|b| b.as_ref()).collect();
        let results = evaluate_all(&s, &refs, opts);

        let found = results.iter().any(|e| e.verdict == Verdict::Promising);
        let beat_hold = results.iter().any(|e| match (e.net, e.benchmark) {
            (Some(n), Some(b)) => n.total_return > b.total_return && e.verdict != Verdict::Refused,
            _ => false,
        });
        let (matched, observed) = match shape {
            Shape::Noise => (!found, format!("{} signal(s) rated promising", results.iter().filter(|e| e.verdict == Verdict::Promising).count())),
            Shape::Trend => (!beat_hold, format!("{} signal(s) beat buy-and-hold", results.iter().filter(|e| matches!((e.net, e.benchmark), (Some(n), Some(b)) if n.total_return > b.total_return)).count())),
            Shape::Crash => {
                let hold_dd = results.iter().find_map(|e| e.benchmark.map(|b| b.max_drawdown)).unwrap_or(0.0);
                let filter_dd = results.iter().find(|e| e.signal == "trend-filter").and_then(|e| e.net.map(|n| n.max_drawdown));
                match filter_dd {
                    Some(f) => (f < hold_dd, format!("trend filter drew down {:.1}% against {:.1}% for holding", f * 100.0, hold_dd * 100.0)),
                    None => (false, "the trend filter produced no result".to_string()),
                }
            }
            Shape::Autocorrelated => (found, format!("{} signal(s) rated promising", results.iter().filter(|e| e.verdict == Verdict::Promising).count())),
        };
        out.push(RegimeResult { shape, expectation: shape.expectation(), results, matched, observed });
    }
    out
}

#[derive(Debug, Clone, PartialEq)]
pub struct MultipleTesting {
    pub trials: usize,
    pub bars: usize,
    /// The largest |t| among signals that are all KNOWN to be worthless.
    pub best_t: f64,
    /// The conventional single-test bar.
    pub naive_bar: f64,
    /// The bar this many trials actually demands.
    pub honest_bar: f64,
    /// How many worthless signals clear the conventional bar. THE NUMBER THAT MATTERS.
    pub pass_naive: usize,
    /// How many clear the honest one.
    pub pass_honest: usize,
    /// What the best of them appeared to return, net.
    pub best_return: f64,
}

/// Run `trials` signals that are KNOWN to be worthless on data that is KNOWN to contain nothing.
///
/// This is the demonstration, and it is not an argument — it is a count. Every signal here is a
/// seeded coin flip and the series is a driftless random walk, so the true answer is zero every
/// time. Whatever clears the conventional bar cleared it by luck, and that is what happens to
/// somebody sweeping parameters without counting how many they tried.
///
/// **Costs are switched off inside this function**, because they are a confound rather than a
/// detail: a signal that trades every bar loses money reliably, and a reliable loss is a real
/// effect with a large t-statistic. The first version of this left them on and reported 40 of 40
/// "significant" — a striking number that was measuring the wrong thing entirely.
pub fn multiple_testing(trials: usize, bars: usize, opts: &EvalOptions) -> MultipleTesting {
    let naive_bar = t_required_for(1);
    let honest_bar = t_required_for(trials);
    let mut best_t = 0.0_f64;
    let mut best_return = 0.0_f64;
    let mut pass_naive = 0usize;
    let mut pass_honest = 0usize;

    for i in 0..trials {
        // A FRESH SERIES PER TRIAL, so the trials are independent. Forty coin flips on ONE series
        // are highly correlated — they are all long about half the time in the same market — so
        // their t-statistics cluster and almost none clear the bar. That is a true fact about
        // correlated trials and it demonstrates nothing about multiple comparisons, which is what
        // this function is for. Real parameter sweeps sit between the two: many signals on one
        // series, correlated, so the effective number of trials is lower than the count and the
        // sqrt(2 ln n) bar is conservative for them.
        let s = series_of(Shape::Noise, bars, 987_654_321 + i as u64 * 7_919);
        let sig = NullControl { seed: 1_000 + i as u64 };
        // Each is judged ALONE, on purpose — this is measuring what a person sees when they look at
        // one result at a time, which is how the mistake is actually made.
        // COSTS ARE OFF HERE, and that is the experiment rather than an oversight. A coin flip
        // trades every bar, so at any real cost it loses money RELIABLY — which is a large negative
        // t-statistic produced by a genuine effect, not by luck. Leaving costs on measured "trading
        // constantly is expensive" and reported it as multiple testing: 40 of 40 "significant",
        // when 5% of 40 should be about two. Luck is the only thing that may vary here.
        let e = evaluate(&s, &sig, &EvalOptions { trials: 1, min_trades: 1, costs: crate::evaluate::Costs::free(), ..*opts });
        let t = e.t_stat.unwrap_or(0.0).abs();
        if t > naive_bar {
            pass_naive += 1;
        }
        if t > honest_bar {
            pass_honest += 1;
        }
        if t > best_t {
            best_t = t;
            best_return = e.net.map(|n| n.total_return).unwrap_or(0.0);
        }
    }

    MultipleTesting { trials, bars, best_t, naive_bar, honest_bar, pass_naive, pass_honest, best_return }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_generated_series_is_a_real_series() {
        for shape in [Shape::Noise, Shape::Trend, Shape::Crash, Shape::Autocorrelated] {
            let bars = synth(shape, 400, 7);
            assert_eq!(bars.len(), 400, "{}", shape.label());
            // Sorted, on weekdays, and every price positive — the properties `check_series` needs
            // and `bars_available_at`'s binary search assumes.
            assert!(bars.windows(2).all(|w| w[0].date() < w[1].date()), "{} is not sorted", shape.label());
            assert!(bars.iter().all(|b| !is_weekend(b.date())), "{} lands on a weekend", shape.label());
            assert!(bars.iter().all(|b| b.close.minor > 0 && b.open.minor > 0), "{} has a non-positive price", shape.label());
            assert!(bars.iter().all(|b| b.high.minor >= b.low.minor), "{} has an impossible bar", shape.label());
        }
    }

    #[test]
    fn the_same_seed_gives_the_same_series() {
        // A simulation nobody can reproduce is an anecdote.
        assert_eq!(synth(Shape::Trend, 200, 42), synth(Shape::Trend, 200, 42));
        assert_ne!(synth(Shape::Trend, 200, 42), synth(Shape::Trend, 200, 43));
    }

    #[test]
    fn the_shapes_actually_differ_in_the_way_they_claim_to() {
        let ret = |shape: Shape| {
            let b = synth(shape, 900, 5);
            (b.last().unwrap().close.minor as f64 - b[0].close.minor as f64) / b[0].close.minor as f64
        };
        // A trend goes up, a crash ends down. If these ever stopped being true the regime checks
        // below would be asserting things about series that are not what they say they are.
        assert!(ret(Shape::Trend) > 0.3, "trend returned {}", ret(Shape::Trend));
        assert!(ret(Shape::Crash) < ret(Shape::Trend), "the crash should give back what the trend keeps");
        // And the autocorrelated one has runs: consecutive same-direction closes, unlike a walk.
        let runs = |shape: Shape| {
            let b = synth(shape, 900, 5);
            b.windows(3).filter(|w| (w[1].close.minor > w[0].close.minor) == (w[2].close.minor > w[1].close.minor)).count()
        };
        assert!(runs(Shape::Autocorrelated) > runs(Shape::Noise), "the autocorrelated shape has no more runs than noise");
    }

    #[test]
    fn the_harness_finds_nothing_in_a_driftless_walk() {
        // THE INSTRUMENT CHECK. A random walk contains nothing, so anything rated promising here is
        // the harness lying — and on real data that failure is invisible.
        let opts = EvalOptions { min_trades: 1, ..EvalOptions::default() };
        for seed in [1u64, 2, 3, 99] {
            let s = series_of(Shape::Noise, 1_200, seed);
            let battery = default_battery();
            let refs: Vec<&dyn Signal> = battery.iter().map(|b| b.as_ref()).collect();
            let out = evaluate_all(&s, &refs, &opts);
            assert!(out.iter().all(|e| e.verdict != Verdict::Promising), "seed {seed}: {:?}", out.iter().map(|e| (e.signal.clone(), e.verdict.label())).collect::<Vec<_>>());
        }
    }

    #[test]
    fn worthless_signals_clear_the_conventional_bar_and_that_is_the_whole_lesson() {
        // Forty coin flips on a driftless walk. The true answer is zero for every one of them, and
        // the count that clears a single-test threshold is not zero — that is what happens to
        // somebody sweeping parameters without counting how many they tried.
        let m = multiple_testing(40, 1_200, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(m.trials, 40);
        assert!(m.honest_bar > m.naive_bar, "the bar must rise with the trial count");
        assert!(m.pass_honest <= m.pass_naive, "the honest bar cannot admit MORE than the naive one");
        // The demonstration is the count itself, whatever it comes out at — pinning an exact number
        // would be pinning the PRNG rather than the phenomenon.
        assert!(m.best_t > 0.0);
        // BUT NOT ALL OF THEM. Under the null about 5% should clear a two-sided 5% bar; if nearly
        // every worthless signal is "significant", this is measuring a systematic effect rather
        // than luck — which is exactly what happened when costs were left on.
        assert!(m.pass_naive < m.trials / 2, "{} of {} cleared the conventional bar — this is measuring an effect, not luck", m.pass_naive, m.trials);
    }

    #[test]
    fn every_regime_reports_whether_it_matched_and_says_what_it_saw() {
        let out = run_regimes(1_000, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(out.len(), 4);
        for r in &out {
            assert!(!r.expectation.is_empty(), "{} has no stated expectation", r.shape.label());
            assert!(!r.observed.is_empty(), "{} observed nothing", r.shape.label());
            assert!(!r.results.is_empty(), "{} produced no results", r.shape.label());
        }
        // The noise regime is the one that must hold, because it is the one where the truth is not
        // a matter of degree: there is nothing there.
        let noise = out.iter().find(|r| r.shape == Shape::Noise).expect("noise ran");
        assert!(noise.matched, "the harness found something in a random walk: {}", noise.observed);
    }

    #[test]
    fn simulated_data_is_marked_as_simulated_everywhere_it_goes() {
        // A simulated result that could be mistaken for a real one is worse than no result.
        let s = series_of(Shape::Trend, 300, 1);
        assert!(s.unverified());
        assert!(s.caveat().unwrap().contains("SIMULATED DATA"));
        assert_eq!(s.meta().source, "simulated");
        let e = evaluate(&s, &NullControl { seed: 1 }, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert!(e.caveats.iter().any(|c| c.contains("SIMULATED DATA")), "the caveat must travel into the result");
    }
}
